import{_ as o,l,o as e,c as i,v as t,p as n,x as E,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"EPE 预算","description":"","frontmatter":{"title":"EPE 预算","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/epe-budget.md","filePath":"litho/epe-budget.md","lastUpdated":1789023840000}'),h={name:"litho/epe-budget.md"};function P(S,a,c,m,_,A){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="epe-预算" tabindex="-1">EPE 预算 <a class="header-anchor" href="#epe-预算" aria-label="Permalink to &quot;EPE 预算&quot;">​</a></h1><div class="epigraph"><p>产品上那条边的纳米，是成像、套刻、掩模与工艺各交一截再合成的；不分解就只会去拧 OPC 或只会去拧工件台。</p><footer>—— 对照 Levinson 对套刻预算的划分方式，以及计算光刻把 EPE 当综合指标的用法（Mack / 产线公开讲义）</footer></div><p><a href="/litho/edge-placement-error">上一课</a>把偏差钉在法向上。缺口是：还没有一张能加减的<strong>预算</strong>——哪些项进 OPC 名义修正，哪些项只能平方和，单层 CD 规格怎样与套刻叠成器件边。主干<a href="/litho/overlay-budget">套刻预算</a>已经会拆 overlay；本课把同类方法用到 EPE。下一单元从薄膜反射另起，不再把驻波冒充成像核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口语「EPE 3 nm」往往是某个统计或某个热点。上一课警告过局部性。缺口接着是：这一包能否拆成光学残差（OPC 之后）、套刻投影、掩模写误差经 MEEF 到边、刻蚀偏置、以及随机 / 计量噪声，从而决定该修模型、改对准，还是改设计余量。不拆，所有超差都会被送到计算光刻。</p><p>独立项用 RSS，已知相关项先合并。CD 误差的一半与 overlay 在法向上往往近乎独立，常用</p> \\[\\mathrm{EPE}_\\mathrm{rss}\\approx\\sqrt{(\\Delta\\mathrm{CD}/2)^2+\\mathrm{OVL}_\\perp^2+\\cdots}. \\]<p>省略号里是 LES、角、像差残差、多层切线。系数 1/2 假定两边对称；单边定义的栅对接触不要硬套。</p><h3 id="可校正与不可校正" tabindex="-1">可校正与不可校正 <a class="header-anchor" href="#可校正与不可校正" aria-label="Permalink to &quot;可校正与不可校正&quot;">​</a></h3><p>名义光学 EPE 进 OPC 迭代，可以压到模型误差地板。剂量 / 焦点窗口内的 PV-band、不可建模的高阶像差、套刻残差、LER，校正环吃不掉。把 PV-band 当成「再跑一夜 OPC」，会高估软件；把套刻残差当成「模型没校准」，会低估机台与工艺。</p><p><span class="marginnote">LELE 的最终缝是两次 EPE 加切线套刻；SADP 的最终节距是 spacer 均匀性加芯轴 EPE。预算行必须按图形化路径改，不能抄单次曝光的 RSS 表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按边类别建表：密线中段、孤立线、线端、内角、孔边缘。每类再分：光学（含照明与薄膜栈）、套刻、掩模、刻蚀、计量。场内 / 场间拆行：镜头与扫描同步进场内，晶圆网格与翘曲进场间——与套刻预算对齐，否则同一项会进两张表。</p><p>浸没矢量与禁戒节距使「光学行」随 pitch 变：禁戒带上光学行突然变大，RSS 被它主导，这时该改规则或照明，而不是加 overlay 机台。</p>',14)),(e(),n(d,null,{default:E(()=>[p(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22OPC%20%E5%90%8E%E5%85%89%E5%AD%A6%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20RSS%5B%22RSS%20%2F%20%E7%9B%B8%E5%85%B3%E5%90%88%E5%B9%B6%22%5D%0A%20%20OVL%5B%22%E5%A5%97%E5%88%BB%E6%B3%95%E5%90%91%E6%8A%95%E5%BD%B1%22%5D%20--%3E%20RSS%0A%20%20MSK%5B%22%E6%8E%A9%E6%A8%A1%20%C3%97%20MEEF%22%5D%20--%3E%20RSS%0A%20%20ET%5B%22%E5%88%BB%E8%9A%80%E5%81%8F%E7%BD%AE%22%5D%20--%3E%20RSS%0A%20%20ST%5B%22%E9%9A%8F%E6%9C%BA%20%2F%20%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20RSS%0A%20%20RSS%20--%3E%20PROD%5B%22%E4%BA%A7%E5%93%81%E8%BE%B9%20EPE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与-nils、敏感度的接口" tabindex="-1">与 NILS、敏感度的接口 <a class="header-anchor" href="#与-nils、敏感度的接口" aria-label="Permalink to &quot;与 NILS、敏感度的接口&quot;">​</a></h3><p>剂量误差预算 \\(\\Delta D/D\\) 经 NILS 换成光学 EPE 行。像差预算 \\(c_j\\) 经上一课序敏感度换成边位移行。焦面倾斜残差换成场上光学行的峰峰值。预算是这些导数的集成，不是另一套物理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>器件失效往往是局部两边相向的 EPE 把间隙吃光，或同向的 EPE 把重叠吃光。RSS 描述统计；热点是确定的系统项（禁戒、角、场曲）叠加随机项。系统项应从 RSS 里拿出来单独列，否则看起来「3σ 还够」，硅上 SRAM 已经桥。这与套刻预算把可校正项扣掉再进残差是同一纪律。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给某节点的 EPE 纳米配额。电学目标（接触电阻、失配）可以把几何 EPE 再加权，那是 DTCO，不是成像定义。禁止把未公开的产品 EPE 规格写进课文。薄膜摆动造成的 CD 摆动属于下一单元，预算里光学行必须声明是否含栈反射；含糊会把 BARC 事故记成 OPC 残差。</p><p>二维图形课序到此结束：孔/端 → 禁戒 → 角 → EPE → 预算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EPE 预算按边类别拆光学、套刻、掩模、刻蚀、随机。</li><li>独立项 RSS；系统热点单独列，不要洗进 3σ。</li><li>多重图形化改行，不抄单次曝光表。</li><li>NILS 与像差敏感度是光学行的导数来源。</li><li>下一单元：胶下薄膜反射，不再扩成像核。</li><li>出处：Levinson（预算纪律）；Mack；Cobb（EPE 作为 OPC 目标）。</li></ul>',9))])}const b=o(h,[["render",P]]);export{B as __pageData,b as default};
